import unittest
from upload import upload_key

class UploadTests(unittest.TestCase):
    def test_scope(self):
        self.assertEqual(upload_key("account-a", "attempt-1"), ("account-a", "attempt-1"))

    def test_same_attempt_in_different_accounts_has_distinct_keys(self):
        self.assertNotEqual(
            upload_key("account-a", "attempt-1"),
            upload_key("account-b", "attempt-1"),
        )

    def test_preserves_values_without_hashing_or_coercion(self):
        account_id = ["account-a"]
        attempt_id = {"attempt": 1}
        key = upload_key(account_id, attempt_id)

        self.assertIsInstance(key, tuple)
        self.assertIs(key[0], account_id)
        self.assertIs(key[1], attempt_id)

